<?php require_once __DIR__.'/../includes/functions.php';need_role(['petugas']);if($_SERVER['REQUEST_METHOD']!=='POST')go('/laporwarga/petugas/daftar_laporan.php');check_csrf();$id=(int)($_POST['id_laporan']??0);$status=$_POST['status']??'';$note=trim($_POST['keterangan']??'');$response=trim($_POST['isi_tanggapan']??'');$s=db()->prepare('SELECT * FROM reports WHERE id_laporan=? AND id_petugas=?');$s->execute([$id,me()['id_user']]);$r=$s->fetch();if(!$r){flash('error','Laporan tidak ditemukan atau bukan penugasan Anda.');go('/laporwarga/petugas/daftar_laporan.php');}if(!in_array($status,status_transitions()[$r['status']]??[],true)||($status==='Ditolak'&&$note==='')||($status==='Perlu Perbaikan'&&$note==='')){flash('error','Transisi status tidak diizinkan. Alasan wajib diisi untuk penolakan atau permintaan perbaikan.');go('/laporwarga/petugas/detail_laporan.php?id='.$id);}try{$pdo=db();$pdo->beginTransaction();$pdo->prepare('UPDATE reports SET status=?,alasan_penolakan=?,updated_at=NOW() WHERE id_laporan=? AND id_petugas=?')->execute([$status,in_array($status,['Ditolak','Perlu Perbaikan'],true)?$note:null,$id,me()['id_user']]);$pdo->prepare('INSERT INTO report_history(id_laporan,id_pengguna,status_sebelumnya,status_baru,keterangan) VALUES(?,?,?,?,?)')->execute([$id,me()['id_user'],$r['status'],$status,$note]);if($response!=='')$pdo->prepare('INSERT INTO responses(id_laporan,id_petugas,isi_tanggapan) VALUES(?,?,?)')->execute([$id,me()['id_user'],$response]);notify((int)$r['id_pelapor'],'Perkembangan laporan '.$r['nomor_laporan'],'Status laporan berubah menjadi '.$status,'/laporwarga/masyarakat/detail_laporan.php?id='.$id);$pdo->commit();log_activity('ubah_status',$r['nomor_laporan'].' -> '.$status);flash('success','Status dan tindak lanjut berhasil disimpan.');go('/laporwarga/petugas/detail_laporan.php?id='.$id);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('error','Gagal menyimpan perubahan.');go('/laporwarga/petugas/detail_laporan.php?id='.$id);}